<?php require __DIR__.'/bootstrap.php';require_admin();$items=read_json('notifications.json',[]);if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(string)($_POST['id']??'');foreach($items as &$n)if($n['id']===$id)$n['read']=true;unset($n);write_json('notifications.json',$items);redirect('admin-notifications.php');}site_header('Notifications'); ?>
<div class="admin-shell"><h1 style="font:42px 'Playfair Display',serif">Notification centre</h1><nav class="admin-nav"><a href="admin.php">Overview</a><a href="admin-products.php">Products</a><a href="admin-orders.php">Orders</a><a href="admin-settings.php">Settings</a><a href="admin-gallery.php">Gallery</a><a href="admin-notifications.php">Notifications</a><a href="admin-subscribers.php">Newsletter</a><a href="admin-requests.php">Custom requests</a><a href="admin-logout.php">Sign out</a></nav><div class="card-panel"><?php foreach($items as $n): ?><div style="display:flex;justify-content:space-between;gap:20px;padding:16px 0;border-bottom:1px solid var(--line)"><div><strong><?= e($n['title']) ?></strong> <?= empty($n['read'])?'<span class="status pending">Unread</span>':'' ?><p class="muted"><?= e($n['message']) ?></p><small><?= e(date('j M Y H:i',strtotime($n['created_at']))) ?> · <?= e($n['type']) ?></small><?php if(!empty($n['order_ref'])): ?><br><a class="text-link" href="admin-orders.php">View orders ↗</a><?php endif; ?></div><?php if(empty($n['read'])): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($n['id']) ?>"><button class="button button-small" type="submit">Mark read</button></form><?php endif; ?></div><?php endforeach; if(!$items)echo '<p>No notifications yet.</p>'; ?></div></div><?php site_footer(); ?>
